package com.example.domain.model.i18n

internal object DuaSo1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Toosidda hurdada", "Mahad naanaysa Allaah, ee na siiyay nolol ka dib markuu na dilay (hurdadii), xaggiisana ayaa loo noqonayaa.", "Waxaa la yiraahdaa isla markiiba markaad hurdada ka toosto si aad Allaah ugu mahadnaqdo.", "Nabigu ﷺ wuxuu ku akhriyi jiray markuu toosay — maalinta ku bilaabid mahadnaq iyo xusuusta aakhiro."),
        "dua_leaving_home" to DuaText("Guriga ka bixidda", "Magaca Allaah ayaan ku bixi; waxaan isku halleeyaa Allaah. Ma jiro xoog iyo awood midna aan ahayn kan Allaah.", "Waxaa la yiraahdaa marka guriga laga baxayo si Allaah loo ilaaliyo.", "Malaa'igtu waxay tiraahdaa: waa lagu hanuuniyay, waa lagaa ilaaliyay oo waa lagaa dhawray, shaydaankuna wuu ka fogaadaa."),
        "dua_anxiety_distress" to DuaText("Ducada walaaca iyo murugada", "Allaahow, waxaan kaa magan galayaa walaaca iyo murugada, tabarta la'aanta iyo caajisnimada, bakhaylnimada iyo fulaynimada, culaabta deynta iyo dadka igu adkaanshihiisa.", "Waqtiga murugada, walaaca, deynta ama cadaadiska maskaxeed.", "Nabigu ﷺ badanaa wuxuu ku ducayn jiray tan — magan gelis ka murugada, caajisnimada iyo deynta."),
        "dua_sayyidul_istighfar" to DuaText("Sayidka ducada dambi dhaafka", "Allaahow, Waxaad tahay Rabbigay; ma jiro ilaah la cabudo aan ahayn adiga. Waad i abuurtay, anna waxaan ahay addoonkaaga, waxaanan ku sii jirayaa ballankaaga iyo yaboohaaga intaan awoodo. Waxaan kaa magan galayaa sharka aan sameeyay. Waxaan qirayaa nicmadaada, waxaanan qirayaa dembigayga, ee ii dambi dhaaf, maxaa yeelay ninna dambi ma dhaafo adiga mooyee.", "Waxaa la yiraahdaa subax iyo galab — ducadii ugu fiicnayd ee toobadda ee Nabigu ﷺ baray.", "Qofkii galabta rumaysad ku dhaha oo habeenkaas dhinta wuxuu geli doonaa Jannada; sidoo kale subaxda."),
        "dua_parents" to DuaText("Ducada waalidka", "Rabbiyow, u naxariiso sida ay iigu koriyeen yarayntayda.", "Ducada Qur'aanka ee waalidka, abaalgud u ah daryeelkoodii carruurnimo.", "Allaah qudhiisa ayaa nagu amray inaan waalidkeenna ku ducaynno tan."),
        "dua_entering_mosque" to DuaText("Masjidka gelidda", "Allaahow, ii fur albaabbada naxariistaada.", "Waxaa la yiraahdaa marka masjidka lagu galayo cagta midig.", "Nabigu ﷺ wuxuu baray ducadan masjidka gelidda."),
        "dua_morning_asbahna" to DuaText("Xusuusta subaxa", "Waxaan gelnay subax, boqortooyada oo dhammuna waa tii Allaah, mahad oo dhammuna waa Allaah. Ma jiro ilaah la cabudo aan ahayn Allaah, kaligiis, shariig ma leh. Isagaa leh boqortooyada iyo mahadda, wax kastana wuu karaa.", "Ducada Sunnada ee subaxa la yiraahdo.", "Maalintu waxay ku bilaabataa qiraalka boqortooyada iyo kalinimada Allaah."),
        "dua_evening_amsayna" to DuaText("Xusuusta galabta", "Waxaan gelnay galab, boqortooyada oo dhammuna waa tii Allaah, mahad oo dhammuna waa Allaah. Ma jiro ilaah la cabudo aan ahayn Allaah, kaligiis, shariig ma leh. Isagaa leh boqortooyada iyo mahadda, wax kastana wuu karaa.", "Ducada Sunnada ee galabta la yiraahdo.", "Habeenku wuxuu ku bilaabmaa qiraalka boqortooyada iyo kalinimada Allaah."),
        "dua_before_sleep" to DuaText("Hurdada ka hor", "Allaahow, magacaaga ayaan ku dhimanayaa (seexanayaa) kuna noolaanayaa (toosayaa).", "Waxaa la yiraahdaa ka dib markii la jiifsaday sariirta.", "Nabigu ﷺ wuxuu ku akhriyi jiray hurdada ka hor."),
        "dua_travel" to DuaText("Ducada safarka", "Waa xurmo leeyahay kii inoo sakhiray tan, annagoo aan awoodi lahayn inaan qudheenna sameyno, dabcan waxaan ku noqonaynaa Rabbigeenna.", "Waxaa la yiraahdaa ka dib markii gaadhiga la fuulo, saddex jeer oo Allaahu Akbar la yiraahdo ka dib.", "Ducada Sunnada ee safarka — ilaalin iyo barako darteed."),
        "dua_ayatul_kursi" to DuaText("Aayatul Kursi salaadda ka dib", "Allaah — ma jiro ilaah aan ahayn isaga, Nool ahaan, ilaaliyaha wax walba. Ma qaban hurdo iyo lulmo toona. Isaga u sugan wax kasta oo samooyinka iyo dhulka ku jira. Yaa ka shafeeci kara isaga oo idan la'aan? Wuu og yahay waxa hore u socda iyo waxa gadaal u socda. Waxbase kama gaari karaan ogaanshihiisa waxa uu doono mooyee. Kursigiisu waa dabooshay samooyinka iyo dhulka, ilaalintooduna ma daalisho. Isagu waa sarreeye weyn.", "Salaad kasta oo fardi ah ka dib iyo hurdada ka hor.", "Qofka salaad kasta oo fardi ah ka dib akhriya, wax ka dhigma ilaa dhimasho oo keliya ayaa ka celinaya Jannada; hurdada ka hor waxay ilaalisaa ilaa subax."),
        "dua_hasbunallah" to DuaText("Allaah baa nagu filan", "Allaah baa nagu filan, isagana waa kii ugu fiicnaa wakiilnimo.", "Waqtiga cabsida cadowga ama khatar weyn.", "Nabi Ibraahim (CS) ayaa tan yiri markii dabka lagu tuuray, Nabiguna ﷺ wuxuu ku hadli jiray waqtiga khatarta."),
        "dua_entering_home" to DuaText("Guriga gelidda", "Magaca Allaah (guriga aan gelayaa).", "Waxaa la sheegaa magaca Allaah lana salaamaa marka guriga la gelayo.", "Marka Allaah lagu xasuusto gelitaanka iyo cuntada, shaydaanku wuxuu yidhaahdaa: halkan ma jiro meel la hoydo iyo casho toona."),
        "dua_yunus" to DuaText("Ducada Nabi Yuunus (CS)", "Ma jiro ilaah aan ahayn adiga, waad nasahsan tahay; runtii waxaan ka mid ahaa dulmiilayaasha.", "Ducada Nabi Yuunus caloosha kalluunka — dhib kasta.", "Muslin kastoo ku ducoodo arrin kasta, Allaah wuu ka jawaabaa."),
        "dua_karb" to DuaText("Ducada dhibta weyn", "Ma jiro ilaah aan ahayn Allaah, Weyn, Dulqaadka leh. Ma jiro ilaah aan ahayn Allaah, Rabbiga Carshiga weyn. Ma jiro ilaah aan ahayn Allaah, Rabbiga samooyinka, Rabbiga dhulka, iyo Rabbiga Carshiga sharafta leh.", "Waxaa la yiraahdaa waqtiga dhibta iyo cusbooneysiga weyn.", "Nabigu ﷺ wuxuu ku hadli jiray waqtiga dhibta."),
    )
}
